import { test } from "node:test";
import assert from "node:assert/strict";
import { createSessionStore } from "../src/portal/store.js";
import { createSessionManager } from "../src/portal/sessions.js";
import { createPortal, hashPassword } from "../src/portal/http.js";

function setup() {
    let t = 1_000_000;
    const clock = { now: () => t, advance: (ms) => void (t += ms) };
    let n = 0;
    const store = createSessionStore({ now: clock.now });
    const sessions = createSessionManager({ store, now: clock.now, generateId: () => `sid-${++n}` });
    const salt = Buffer.from("pepper-salt");
    const users = new Map([["dana@clinic.test", { id: "u-dana", salt, hash: hashPassword("correct horse", salt) }]]);
    const portal = createPortal({ sessions, users });
    const cookieOf = (res) => /sid=([^;]*)/.exec(res.headers["set-cookie"])[1];
    const req = (sid, body, query) => ({ headers: { cookie: sid ? `sid=${sid}` : "" }, body, query });
    return { clock, store, sessions, portal, req, cookieOf };
}

const creds = { email: "dana@clinic.test", password: "correct horse" };

test("anonymous intake visit creates a session cookie", () => {
    const { portal, req, cookieOf } = setup();
    const res = portal.intake(req(null, null, { draft: "knee pain" }));
    assert.equal(res.status, 200);
    assert.equal(cookieOf(res), "sid-1");
});

test("wrong password is rejected and does not touch the session", () => {
    const { portal, req, sessions } = setup();
    const sid = sessions.start();
    const res = portal.login(req(sid, { email: creds.email, password: "nope" }));
    assert.equal(res.status, 401);
    assert.equal(sessions.resolve(sid).userId, null);
});

test("login issues a new session id instead of reusing the pre-login one", () => {
    const { portal, req, cookieOf } = setup();
    const anon = cookieOf(portal.intake(req(null, null, {})));
    const res = portal.login(req(anon, creds));
    console.log("session id before login:", anon, "after login:", cookieOf(res));
    assert.equal(res.status, 200);
    assert.notEqual(cookieOf(res), anon, "the session id must change when the user authenticates");
});

test("a session id planted before login cannot be used to read the account", () => {
    const { portal, req, cookieOf } = setup();
    const planted = cookieOf(portal.intake(req(null, null, {})));
    portal.login(req(planted, creds));
    const res = portal.me(req(planted));
    assert.equal(res.status, 401, "the old pre-login id must not be signed in");
});

test("the intake draft survives login under the new session", () => {
    const { portal, req, cookieOf } = setup();
    const anon = cookieOf(portal.intake(req(null, null, { draft: "knee pain" })));
    const fresh = cookieOf(portal.login(req(anon, creds)));
    assert.deepEqual(portal.me(req(fresh)).body, { userId: "u-dana", draft: "knee pain" });
});

test("login without any prior session still works", () => {
    const { portal, req, cookieOf } = setup();
    const res = portal.login(req(null, creds));
    assert.equal(portal.me(req(cookieOf(res))).status, 200);
});

test("sessions expire after the idle timeout", () => {
    const { portal, req, cookieOf, clock } = setup();
    const sid = cookieOf(portal.login(req(null, creds)));
    clock.advance(16 * 60_000);
    assert.equal(portal.me(req(sid)).status, 401);
});

test("logout destroys the session", () => {
    const { portal, req, cookieOf, store } = setup();
    const sid = cookieOf(portal.login(req(null, creds)));
    portal.logout(req(sid));
    assert.equal(portal.me(req(sid)).status, 401);
    assert.equal(store.size(), 0);
});
